        selected = set(fields["member_ids"])
        for asset in Asset.objects(project_id=project.id):
            active_reviewers = {reviewer for stage in asset.stages for reviewer in stage.reviewer_ids}
            if asset.status == "in_review" and not active_reviewers.issubset(selected):
                raise AppError(409, "ACTIVE_ASSIGNMENTS", "Reassign active reviews before removing a project member.")
    for name, value in fields.items():
        setattr(project, name, value)
    project.updated_at = now()
