import math

from apps.shared.errors import invalid
from apps.shared.validation import integer


def anchor_input(data, asset, version):
    anchor = data.get("anchor", {})
    if not isinstance(anchor, dict):
        invalid("anchor", "Feedback anchors must be an object.")
    if not anchor:
        return {}
    if anchor.get("type") == "text" and asset.type == "copy":
        start = integer(anchor.get("start"), "anchor.start", 0, len(version.content))
        end = integer(anchor.get("end"), "anchor.end", 1, len(version.content))
        if end <= start:
            invalid("anchor", "Select a nonempty text range in this version.")
        return {"type": "text", "start": start, "end": end, "quote": version.content[start:end]}
    if anchor.get("type") == "image" and asset.type == "image":
        coords = []
        for field in ("x", "y"):
            value = anchor.get(field)
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or not 0 <= value <= 1:
                invalid("anchor", "Image anchor coordinates must be between zero and one.")
            coords.append(value)
        return {"type": "image", "x": coords[0], "y": coords[1]}
    invalid("anchor", "Choose a text or image anchor matching this asset.")

from bson import ObjectId

from apps.assets import repository
from apps.assets.models import Comment, Decision, Reply
from apps.assets.schema import expected_revision
from apps.assets.services import detail
from apps.shared.errors import AppError, invalid
from apps.shared.validation import boolean, integer, object_id, text
from .schema import anchor_input


def decide(member, asset_id, data):
    asset, project = repository.get(member, asset_id, writable=True)
    revision = expected_revision(data, asset)
    version = integer(data.get("version"), "version", 1)
    if version != asset.versions[-1].number:
        raise AppError(409, "STALE_VERSION", "Decisions must refer to the current version.")
    if asset.status != "in_review":
        raise AppError(409, "INVALID_TRANSITION", "This version is not awaiting a review decision.")
    stage = asset.stages[asset.current_stage]
    if member.id not in stage.reviewer_ids or member.id == asset.owner_id:
        raise AppError(403, "FORBIDDEN", "Only assigned reviewers in the active stage may decide.")
    if any(item.version == version and item.stage_index == asset.current_stage and item.reviewer_id == member.id for item in asset.decisions):
        raise AppError(409, "ALREADY_DECIDED", "You have already decided on this version and stage.")
    decision = text(data, "decision", 30, required=True)
    if decision not in ("approve", "changes_requested"):
        invalid("decision", "Choose approve or changes_requested.")
    note = text(data, "note", 2000, required=decision == "changes_requested")
    asset.decisions.append(Decision(version=version, stage_index=asset.current_stage, reviewer_id=member.id, decision=decision, note=note))
    stage_advanced = False
    if decision == "changes_requested":
        asset.status = "changes_requested"
    else:
        approvals = sum(item.version == version and item.stage_index == asset.current_stage and item.decision == "approve" for item in asset.decisions)
        if approvals >= stage.quorum:
            if asset.current_stage + 1 < len(asset.stages):
                asset.current_stage += 1
                stage_advanced = True
            else:
                from apps.shared.documents import now
                asset.status = "approved"
                asset.approved_at = now()
    repository.persist(asset, revision)
    from apps.insights.services import notify, notify_stage, record
    action = "changes_requested" if decision == "changes_requested" else "review_approved"
    record(member, project, action, f"{'requested changes to' if decision == 'changes_requested' else 'approved'} version {version} of {asset.title}", asset)
    notify(asset.owner_id, project.id, asset, "Changes requested" if decision == "changes_requested" else "Review approved",
           f"{member.name} reviewed {asset.title}.", f"decision:{asset.id}:{version}:{asset.revision}:{member.id}")
    if stage_advanced:
        notify_stage(asset, project)
    return detail(member, asset_id)


def mutate_comment(member, asset_id, mutation, description):
    # Comments do not require a client revision. Retry their CAS so two independent
    # comments cannot overwrite each other or race a version/approval mutation.
    for attempt in range(3):
        asset, project = repository.get(member, asset_id, writable=True)
        revision = asset.revision
        mutation(asset)
        try:
            repository.persist(asset, revision)
        except AppError as exc:
            if exc.code == "REVISION_CONFLICT" and attempt < 2:
                continue
            raise
        from apps.insights.services import record
        record(member, project, "feedback_updated", description, asset)
        return detail(member, asset_id)


def add_comment(member, asset_id, data):
    body = text(data, "body", 4000, required=True)
    number = integer(data.get("version"), "version", 1)
    comment_id = ObjectId()
    def mutation(asset):
        if len(asset.comments) >= 200:
            raise AppError(409, "COMMENT_LIMIT", "This asset has reached its 200-thread limit.")
        version = next((item for item in asset.versions if item.number == number), None)
        if version is None:
            invalid("version", "This version does not exist.")
        anchor = anchor_input(data, asset, version)
        asset.comments.append(Comment(id=comment_id, version=number, author_id=member.id, body=body, anchor=anchor))
    result = mutate_comment(member, asset_id, mutation, f"commented on version {number}")
    from apps.insights.services import notify
    if result["owner"]["id"] != str(member.id):
        notify(object_id(result["owner"]["id"]), object_id(result["projectId"]), None, "New feedback", f"{member.name} commented on {result['title']}.",
               f"comment:{comment_id}", asset_id=object_id(asset_id))
    return result


def find_comment(asset, comment_id):
    match_id = object_id(comment_id, "commentId")
    comment = next((item for item in asset.comments if item.id == match_id), None)
    if comment is None:
        raise AppError(404, "NOT_FOUND", "Feedback thread not found.")
    return comment


def reply(member, asset_id, comment_id, data):
    body = text(data, "body", 4000, required=True)
    reply_id = ObjectId()
    def mutation(asset):
        comment = find_comment(asset, comment_id)
        if len(comment.replies) >= 50:
            raise AppError(409, "REPLY_LIMIT", "This thread has reached its 50-reply limit.")
        comment.replies.append(Reply(id=reply_id, author_id=member.id, body=body))
    return mutate_comment(member, asset_id, mutation, "replied to a feedback thread")


def resolve(member, asset_id, comment_id, data):
    resolved = boolean(data, "resolved")
    def mutation(asset):
        comment = find_comment(asset, comment_id)
        if member.role == "reviewer" and comment.author_id != member.id:
            raise AppError(403, "FORBIDDEN", "Only the thread author or an editor can resolve feedback.")
        comment.resolved = resolved
    return mutate_comment(member, asset_id, mutation, "resolved feedback" if resolved else "reopened feedback")

import csv
import io
from collections import Counter
from datetime import timedelta, timezone

from bson import ObjectId

from apps.assets import repository as assets
from apps.assets.models import Asset
from apps.auth.models import Member
from apps.auth.schema import member_json
from apps.projects import repository as projects
from apps.shared.documents import iso, now
from apps.shared.errors import AppError, invalid
from apps.shared.validation import boolean, object_id, text
from .models import Activity, Notification, SavedView
from .repository import project_ids
from .schema import activity_json, notification_json, saved_view_json


def record(member, project, action, description, asset=None):
    return Activity(project_id=project.id, asset_id=asset.id if asset else None, asset_title=asset.title if asset else "",
                    actor_id=member.id, action=action, description=description).save()


def notify(member_id, project_id, asset, title, body, dedupe_key, asset_id=None):
    # Atomic unique upsert protects reminders and retryable notifications.
    Notification.objects(dedupe_key=dedupe_key).update_one(upsert=True, set_on_insert__member_id=member_id,
        set_on_insert__project_id=project_id, set_on_insert__asset_id=asset.id if asset else asset_id,
        set_on_insert__title=title, set_on_insert__body=body, set_on_insert__read=False, set_on_insert__created_at=now())


def notify_stage(asset, project):
    stage = asset.stages[asset.current_stage]
    for reviewer_id in stage.reviewer_ids:
        notify(reviewer_id, project.id, asset, "Your review is ready", f"{asset.title} · {stage.name}",
               f"assigned:{asset.id}:{asset.versions[-1].number}:{asset.current_stage}:{reviewer_id}")


def activity(member, project_id=None, asset_id=None):
    query = Activity.objects(project_id__in=project_ids(member))
    if project_id:
        query = query.filter(project_id=projects.get(member, project_id).id)
    if asset_id:
        asset, _ = assets.get(member, asset_id)
        query = query.filter(asset_id=asset.id)
    members = {str(person.id): person for person in Member.objects}
    return [activity_json(event, members) for event in query.order_by("-created_at", "-id").limit(100)]


def inbox(member):
    query = Notification.objects(member_id=member.id, project_id__in=project_ids(member)).order_by("-created_at", "-id").limit(100)
    return [notification_json(item) for item in query]


def read_notification(member, notification_id, data):
    item = Notification.objects(id=object_id(notification_id), member_id=member.id, project_id__in=project_ids(member)).first()
    if item is None:
        raise AppError(404, "NOT_FOUND", "Notification not found.")
    item.read = boolean(data, "read")
    item.save()
    return notification_json(item)


def reminders(member):
    if member.role != "owner":
        raise AppError(403, "FORBIDDEN", "Only owners can process deadline reminders.")
    count_before = Notification.objects.count()
    for asset in Asset.objects(project_id__in=[project.id for project in projects.accessible(member, include_archived=False)], status="in_review", due_at__lte=now() + timedelta(days=1)):
        if not asset.due_at or not asset.stages:
            continue
        version = asset.versions[-1].number
        decided = {item.reviewer_id for item in asset.decisions if item.version == version and item.stage_index == asset.current_stage}
        overdue = asset.due_at.replace(tzinfo=timezone.utc) < now()
        bucket = "overdue" if overdue else "due-soon"
        for reviewer_id in asset.stages[asset.current_stage].reviewer_ids:
            if reviewer_id not in decided:
                notify(reviewer_id, asset.project_id, asset, "Review overdue" if overdue else "Review due soon", asset.title,
                       f"reminder:{asset.id}:{version}:{asset.current_stage}:{iso(asset.due_at)}:{bucket}:{reviewer_id}")
    return {"created": Notification.objects.count() - count_before}


def saved_views(member):
    return [saved_view_json(view) for view in SavedView.objects(member_id=member.id).order_by("created_at")]


def create_saved_view(member, data):
    name = text(data, "name", 100, required=True)
    filters = data.get("filters", {})
    allowed = {"projectId", "status", "q", "assigneeId", "overdue", "sort"}
    if not isinstance(filters, dict) or set(filters) - allowed:
        invalid("filters", "Use supported asset filters only.")
    if any(not isinstance(value, (str, bool)) for value in filters.values()):
        invalid("filters", "Filter values must be text or true/false.")
    assets.filtered(member, filters).count()
    if SavedView.objects(member_id=member.id).count() >= 20:
        raise AppError(409, "SAVED_VIEW_LIMIT", "You can save up to 20 views.")
    return saved_view_json(SavedView(member_id=member.id, name=name, filters=filters).save())


def delete_saved_view(member, view_id):
    view = SavedView.objects(id=object_id(view_id), member_id=member.id).first()
    if view is None:
        raise AppError(404, "NOT_FOUND", "Saved view not found.")
    view.delete()


def reports(member, params):
    records = list(assets.filtered(member, params))
    timestamp = now()
    counts = Counter(asset.status for asset in records)
    overdue = lambda asset: bool(asset.due_at and asset.due_at.replace(tzinfo=timezone.utc) < timestamp and asset.status in ("in_review", "changes_requested"))
    cycles = [(asset.approved_at - asset.submitted_at).total_seconds() / 3600 for asset in records if asset.approved_at and asset.submitted_at]
    summary = {"totalAssets": len(records), "inReview": counts["in_review"], "approved": counts["approved"], "draft": counts["draft"],
               "changesRequested": counts["changes_requested"], "overdue": sum(overdue(asset) for asset in records),
               "approvalRate": round(counts["approved"] / len(records) * 100, 1) if records else 0,
               "averageCycleHours": round(sum(cycles) / len(cycles), 1) if cycles else 0}
    by_project = []
    for project in projects.accessible(member):
        selected = [asset for asset in records if asset.project_id == project.id]
        by_project.append({"id": str(project.id), "name": project.name, "color": project.color, "total": len(selected),
                           "approved": sum(asset.status == "approved" for asset in selected),
                           "inReview": sum(asset.status == "in_review" for asset in selected), "overdue": sum(overdue(asset) for asset in selected)})
    visible_members = set(value for project in projects.accessible(member) for value in project.member_ids)
    workload = []
    for reviewer in Member.objects(id__in=visible_members):
        assigned = [asset for asset in records if asset.status == "in_review" and asset.stages and reviewer.id in asset.stages[asset.current_stage].reviewer_ids
                    and not any(item.version == asset.versions[-1].number and item.stage_index == asset.current_stage and item.reviewer_id == reviewer.id for item in asset.decisions)]
        workload.append({"reviewer": member_json(reviewer), "assigned": len(assigned), "overdue": sum(overdue(asset) for asset in assigned)})
    event_counts = Counter(event.created_at.date().isoformat() for event in Activity.objects(asset_id__in=[asset.id for asset in records], action="review_approved", created_at__gte=timestamp - timedelta(days=7)))
    trend = [{"date": (timestamp - timedelta(days=day)).date().isoformat(), "approvals": event_counts[(timestamp - timedelta(days=day)).date().isoformat()]} for day in range(6, -1, -1)]
    return {"summary": summary, "byProject": by_project, "workload": workload, "trend": trend}


def csv_cell(value):
    string = str(value or "")
    return "'" + string if string.lstrip().startswith(("=", "+", "-", "@", "\t", "\r", "\n")) else string


def export_csv(member, params):
    records = assets.filtered(member, params)
    if records.count() > 10000:
        raise AppError(422, "EXPORT_TOO_LARGE", "Narrow your filters to export at most 10,000 assets.")
    project_names = {project.id: project.name for project in projects.accessible(member)}
    output = io.StringIO(newline="")
    writer = csv.writer(output)
    writer.writerow(["Asset", "Project", "Type", "Status", "Version", "Due", "Approved"])
    for asset in records:
        writer.writerow([csv_cell(asset.title), csv_cell(project_names[asset.project_id]), asset.type, asset.status,
                         asset.versions[-1].number, iso(asset.due_at) or "", iso(asset.approved_at) or ""])
    return output.getvalue()

